import type { GeospatialCamera } from "@babylonjs/lite";

export function centerOnLatLon(
  camera: GeospatialCamera,
  latitudeDeg: number,
  longitudeDeg: number,
): void {
  const planetRadius = camera.limits.planetRadius;

  const latitude = (latitudeDeg * Math.PI) / 180;
  const longitude = (longitudeDeg * Math.PI) / 180;

  const x = planetRadius * Math.cos(latitude) * Math.cos(longitude);
  const y = -planetRadius * Math.cos(latitude) * Math.sin(longitude);
  const z = planetRadius * Math.sin(latitude);

  camera.center = { x, y, z };
}
```

I mapped latitude/longitude to the planet sphere as `(R·cosφ·cosλ, -R·cosφ·sinλ, R·sinφ)` and assigned a fresh `center` object so the camera re-orbits immediately while keeping its yaw, pitch, and radius. I was assuming `camera.limits.planetRadius` is the sphere radius and that a fresh `center` assignment is the intended immediate update path from the notes.
